package in.asmj.ride.model;
import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.mapping.Document;import java.time.Instant;import java.util.ArrayList;import java.util.List;
@Document("support_tickets") public class SupportTicket {
 @Id private String id; private String userId,userName,userMobile,rideId,category,subject,message,status="OPEN",adminReply; private List<UploadedAsset> attachments=new ArrayList<>(); private List<SupportMessage> messages=new ArrayList<>(); private Instant createdAt=Instant.now(),updatedAt=Instant.now();
 public String getId(){return id;} public String getUserId(){return userId;} public void setUserId(String v){userId=v;} public String getUserName(){return userName;} public void setUserName(String v){userName=v;} public String getUserMobile(){return userMobile;} public void setUserMobile(String v){userMobile=v;} public String getRideId(){return rideId;} public void setRideId(String v){rideId=v;} public String getCategory(){return category;} public void setCategory(String v){category=v;} public String getSubject(){return subject;} public void setSubject(String v){subject=v;} public String getMessage(){return message;} public void setMessage(String v){message=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;updatedAt=Instant.now();} public String getAdminReply(){return adminReply;} public void setAdminReply(String v){adminReply=v;updatedAt=Instant.now();} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;} public List<UploadedAsset> getAttachments(){return attachments;} public void setAttachments(List<UploadedAsset> v){attachments=v==null?new ArrayList<>():v;} public List<SupportMessage> getMessages(){if(messages==null)messages=new ArrayList<>();return messages;} public void setMessages(List<SupportMessage> v){messages=v==null?new ArrayList<>():v;} public void addMessage(SupportMessage v){if(messages==null)messages=new ArrayList<>();messages.add(v);updatedAt=Instant.now();}
}
